 10875  /* Copy parameters to dynamic space.
 10876   * 1) POP original parameter out;
 10877   * 2) Push and copy original values to dynamic space.
 10878   * The copy instruction format:
 10879   *   Part a: param count
 10880   *   Part b: all param total cell num
 10881   *   Part c: each param's cell_num, src offset and dst offset
 10882   *   Part d: each param's src offset
 10883   *   Part e: each param's dst offset
 10884   */
 10885  static bool
 10886  copy_params_to_dynamic_space(WASMLoaderContext *loader_ctx, char *error_buf,
 10887                               uint32 error_buf_size)
 10888  {
 10889      bool ret = false;
 10890      int16 *frame_offset = NULL;
 10891      uint8 *cells = NULL, cell;
 10892      int16 *src_offsets = NULL;
 10893      uint8 *emit_data = NULL;
 10894      uint32 i;
 10895      BranchBlock *block = loader_ctx->frame_csp - 1;
 10896      BlockType *block_type = &block->block_type;
 10897      WASMFuncType *wasm_type = block_type->u.type;
 10898      uint32 param_count = block_type->u.type->param_count;
 10899      int16 condition_offset = 0;
 10900      bool disable_emit = false;
 10901      bool is_if_block = (block->label_type == LABEL_TYPE_IF ? true : false);
 10902      int16 operand_offset = 0;
 10903
 10904      uint64 size = (uint64)param_count * (sizeof(*cells) + sizeof(*src_offsets));
 10905      bh_assert(size > 0);
 10906
 10907      /* For if block, we also need copy the condition operand offset. */
 10908      if (is_if_block)
 10909          size += sizeof(*cells) + sizeof(*src_offsets);
 10910
 10911      /* Allocate memory for the emit data */
 10912      if (!(emit_data = loader_malloc(size, error_buf, error_buf_size)))
 10913          return false;
 10914
 10915      cells = emit_data;
 10916      src_offsets = (int16 *)(cells + param_count);
 10917
 10918      if (is_if_block)
 10919          condition_offset = *loader_ctx->frame_offset;
 10920
 10921      /* POP original parameter out */
 10922      for (i = 0; i < param_count; i++) {
 10923          POP_OFFSET_TYPE(wasm_type->types[param_count - i - 1]);
 10924          wasm_loader_emit_backspace(loader_ctx, sizeof(int16));
 10925      }
 10926      frame_offset = loader_ctx->frame_offset;
 10927
 10928      /* Get each param's cell num and src offset */
 10929      for (i = 0; i < param_count; i++) {
 10930          cell = (uint8)wasm_value_type_cell_num(wasm_type->types[i]);
 10931          cells[i] = cell;
 10932          src_offsets[i] = *frame_offset;
 10933          frame_offset += cell;
 10934      }
 10935      /* emit copy instruction */
 10936      emit_label(EXT_OP_COPY_STACK_VALUES);
 10937      /* Part a) */
 10938      emit_uint32(loader_ctx, is_if_block ? param_count + 1 : param_count);
 10939      /* Part b) */
 10940      emit_uint32(loader_ctx, is_if_block ? wasm_type->param_cell_num + 1
 10941                                          : wasm_type->param_cell_num);
 10942      /* Part c) */
 10943      for (i = 0; i < param_count; i++)
 10944          emit_byte(loader_ctx, cells[i]);
 10945      if (is_if_block)
 10946          emit_byte(loader_ctx, 1);
 10947
 10948      /* Part d) */
 10949      for (i = 0; i < param_count; i++)
 10950          emit_operand(loader_ctx, src_offsets[i]);
 10951      if (is_if_block)
 10952          emit_operand(loader_ctx, condition_offset);
 10953
 10954      /* Since the start offset to save the block's params and
 10955       * the start offset to save the block's results may be
 10956       * different, we remember the dynamic offset for loop block
 10957       * so that we can use it to copy the stack operands to the
 10958       * loop block's params in wasm_loader_emit_br_info. */
 10959      if (block->label_type == LABEL_TYPE_LOOP)
 10960          block->start_dynamic_offset = loader_ctx->dynamic_offset;
 10961
 10962      /* Part e) */
 10963      /* Push to dynamic space. The push will emit the dst offset. */
 10964      for (i = 0; i < param_count; i++)
 10965          PUSH_OFFSET_TYPE(wasm_type->types[i]);
 10966      if (is_if_block)
 10967          PUSH_OFFSET_TYPE(VALUE_TYPE_I32);
 10968
 10969      ret = true;
 10970
 10971  fail:
 10972      /* Free the emit data */
 10973      wasm_runtime_free(emit_data);
 10974
 10975      return ret;
 10976  }
 10977  #endif
