 11130  /* Read leb without malformed format check */
 11131  static uint64
 11132  read_leb_quick(uint8 **p_buf, uint32 maxbits, bool sign)
 11133  {
 11134      uint8 *buf = *p_buf;
 11135      uint64 result = 0, byte = 0;
 11136      uint32 shift = 0;
 11137
 11138      do {
 11139          byte = *buf++;
 11140          result |= ((byte & 0x7f) << shift);
 11141          shift += 7;
 11142      } while (byte & 0x80);
 11143
 11144      if (sign && (shift < maxbits) && (byte & 0x40)) {
 11145          /* Sign extend */
 11146          result |= (~((uint64)0)) << shift;
 11147      }
 11148
 11149      *p_buf = buf;
 11150      return result;
 11151  }
